mapper.select:
SELECT #{producerId} AS producerId,
/* 오늘 매출 */ ( SELECT NVL(SUM(oi.line_total_amount), 0) FROM ORDERS_ITEM oi JOIN PRODUCT p ON oi.product_id = p.product_id JOIN ORDERS o ON oi.order_id = o.order_id WHERE p.producer_id = #{producerId} AND TRUNC(o.created_date) = TRUNC(SYSDATE) AND o.order_status IN ('PAID', 'SHIPPED', 'DELIVERED') ) AS todaySalesAmount,
/* 이번달 매출 */ ( SELECT NVL(SUM(oi.line_total_amount), 0) FROM ORDERS_ITEM oi JOIN PRODUCT p ON oi.product_id = p.product_id JOIN ORDERS o ON oi.order_id = o.order_id WHERE p.producer_id = #{producerId} AND TRUNC(o.created_date, 'MM') = TRUNC(SYSDATE, 'MM') AND o.order_status IN ('PAID', 'SHIPPED', 'DELIVERED') ) AS monthSalesAmount,
/* 신규 주문 수 (오늘 생성된 주문) — 상품 한 개라도 producer 소유면 1건으로 센다 */ ( SELECT COUNT(DISTINCT o.order_id) FROM ORDERS_ITEM oi JOIN PRODUCT p ON oi.product_id = p.product_id JOIN ORDERS o ON oi.order_id = o.order_id WHERE p.producer_id = #{producerId} AND TRUNC(o.created_date) = TRUNC(SYSDATE) AND o.order_status IN ('ORDERED', 'PAID', 'READY') ) AS newOrderCount
FROM DUAL
